/* 801C8B14-801C8CA0       .text cursorMainMove__12dMenu_Item_cFv */
void dMenu_Item_c::cursorMainMove() {
    stick->checkTrigger();
    u8 oldItem = mNowItem;

    if (stick->checkRightTrigger()) {
        if (mNowItem != 0x15) {
            if (mNowItem % 7 == 6) {
                mNowItem -= 6;
            } else {
                mNowItem += 1;
            }
        }
    } else if (stick->checkLeftTrigger()) {
        if (mNowItem != 0x15) {
            if (mNowItem % 7 == 0) {
                mNowItem += 6;
            } else {
                mNowItem -= 1;
            }
        }
    }

    if (stick->checkUpTrigger()) {
        if (mNowItem == 0x15) {
            mNowItem = 0xE;
        } else if (mNowItem > 6) {
            mNowItem -= 7;
        }
    } else if (stick->checkDownTrigger()) {
        if (mNowItem < 0xE) {
            mNowItem += 7;
        } else if (mNowItem >= 0xE) {
            if (mNowItem <= 0x14) {
                mNowItem = 0x15;
            }
        }
    }

    if (mNowItem != oldItem) {
        m858.mUserArea = 0;
        itemnameSet();
        mDoAud_seStart(JA_SE_ITM_MENU_CURSOR);
    }
}

/* 801C8CA0-801C8E60       .text cursorSubMove__12dMenu_Item_cFv */
void dMenu_Item_c::cursorSubMove() {
    s16 maxItems = g_menuHIO.field_0x82;
    u8 idx;

    if (mNowItem == 0xFF) {
        idx = 8;
    } else {
        idx = mNowItem - m2400;
    }

    stick->checkTrigger();

    if (stick->checkRightTrigger()) {
        if (idx % 3 != 2) {
            if (idx <= maxItems - 1) {
                idx += 1;
            }
        }
    } else if (stick->checkLeftTrigger()) {
        if (idx % 3 != 0) {
            idx -= 1;
        }
    }

    if (stick->checkUpTrigger()) {
        if (idx >= 3) {
            idx -= 3;
        }
    } else if (stick->checkDownTrigger()) {
        if ((u8)(idx + 3) <= maxItems) {
            idx += 3;
        }
    }

    if (idx != (u8)(mNowItem - m2400)) {
        if (idx == 8) {
            if (mNowItem != 0xFF) {
                mNowItem = 0xFF;
                mDoAud_seStart(JA_SE_ITM_MENU_CURSOR);
            }
        } else {
            mNowItem = idx + m2400;
            mDoAud_seStart(JA_SE_ITM_MENU_CURSOR);
        }

        m858.mUserArea = 0;
        itemnameSet();
    }
}

